import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  SyncGroup Request (Version: 0) => group_id generation_id member_id [assignments]
    group_id => STRING
    generation_id => INT32
    member_id => STRING
    assignments => member_id assignment
      member_id => STRING
      assignment => BYTES
*/
export function createRequest(groupId, generationId, memberId, _groupInstanceId, _protocolType, _protocolName, assignments) {
    return Writer.create()
        .appendString(groupId, false)
        .appendInt32(generationId)
        .appendString(memberId, false)
        .appendArray(assignments, (w, assignment) => w.appendString(assignment.memberId, false).appendBytes(assignment.assignment, false), false, false);
}
/*
  SyncGroup Response (Version: 0) => error_code assignment
    error_code => INT16
    assignment => BYTES
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const response = {
        throttleTimeMs: 0,
        errorCode: reader.readInt16(),
        protocolType: null,
        protocolName: null,
        assignment: reader.readBytes(false)
    };
    if (response.errorCode !== 0) {
        throw new ResponseError(apiKey, apiVersion, { '/': [response.errorCode, null] }, response);
    }
    return response;
}
export const api = createAPI(14, 0, createRequest, parseResponse, false, false);
